(function () {
  'use strict';
  if (window.jrDTmu) return;
  const bundle = "";
  const pyodideBase = 'https://cdn.jsdelivr.net/pyodide/v314.0.8/full/';
  const scriptSource = typeof document === 'object' ? document.currentScript?.src : null;
  const resourcesURL = scriptSource ? new URL('pyodide-resources.js', scriptSource).href : null;
  const loadingLimit = 120000;
  const searchLimit = 45000;
  let resourcesPromise = null;
  let worker = null, workerURL = null, ready = false, active = null, serial = 0;

  function loadResources() {
    if (window.jrDTmuResources) return Promise.resolve(window.jrDTmuResources);
    // Small inline previews can still use the CDN. The complete homepage ships
    // its own Python runtime, including when it is opened directly from disk.
    if (!resourcesURL) return Promise.resolve(null);
    if (!resourcesPromise) {
      resourcesPromise = new Promise((resolve, reject) => {
        const script = document.createElement('script');
        script.src = resourcesURL;
        script.async = true;
        script.onload = () => {
          script.remove();
          const resources = window.jrDTmuResources;
          if (resources?.version === '314.0.8' && resources.payload) resolve(resources);
          else reject(new Error('The search files are incomplete. Refresh the homepage and try again.'));
        };
        script.onerror = () => {
          script.remove();
          reject(new Error('The search files could not open. Keep the assets folder beside the homepage and refresh.'));
        };
        document.head.append(script);
      }).catch(error => { resourcesPromise = null; throw error; });
    }
    return resourcesPromise;
  }

  // A module worker keeps Python computation away from the page's UI thread.
  function workerMain() {
    // This helper runs inside the search worker. The resources are shipped with
// the homepage, so neither file:// nor HTTPS use needs a CDN request.
async function loadOfflinePyodide(packedResources) {
  if (packedResources?.version !== '314.0.8' || packedResources.encoding !== 'gzip-base64') {
    throw Error('The bundled Python engine has an unsupported version.');
  }
  const bytesFromBase64 = value => {
    const binary = atob(value), bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    return bytes;
  };
  const compressed = bytesFromBase64(packedResources.payload);
  const stream = new Blob([compressed]).stream().pipeThrough(new DecompressionStream('gzip'));
  const encodedFiles = JSON.parse(await new Response(stream).text());
  const files = new Map(Object.entries(encodedFiles).map(([name, value]) => [name, bytesFromBase64(value)]));
  const base = 'https://dtmu.invalid/pyodide/314.0.8/';
  const decoder = new TextDecoder();
  const lock = JSON.parse(decoder.decode(files.get('pyodide-lock.json')));
  // Data modules also work when the containing page was opened with file://;
  // opaque local-file origins can reject otherwise equivalent Blob modules.
  const moduleURL = name => 'data:text/javascript;base64,' + encodedFiles[name];
  // Pyodide uses fetch for Wasm, stdlib, and wheels. Return the exact packaged
  // bytes with the expected MIME type. Unlisted requests fail locally.
  const originalFetch = globalThis.fetch;
  globalThis.fetch = async (input) => {
    const url = typeof input === 'string' ? input : input?.url || String(input);
    if (!url.startsWith(base)) throw Error('Unexpected resource requested by the bundled Python engine.');
    const name = decodeURIComponent(url.slice(base.length).split(/[?#]/)[0]);
    const bytes = files.get(name);
    if (!bytes) throw Error('The bundled Python engine is missing ' + name + '.');
    const type = name.endsWith('.wasm') ? 'application/wasm' : name.endsWith('.json') ? 'application/json' : 'application/octet-stream';
    return new Response(bytes, {status: 200, headers: {'Content-Type': type}});
  };
  try {
    const [{loadPyodide}, {default: createPyodideModule}] = await Promise.all([
      import(moduleURL('pyodide.mjs')),
      import(moduleURL('pyodide.asm.mjs'))
    ]);
    const python = await loadPyodide({
      indexURL: base,
      packageBaseUrl: base,
      createPyodideModule,
      lockFileContents: lock,
      stdout() {},
      stderr() {}
    });
    await python.loadPackage('numpy');
    return python;
  } finally {
    globalThis.fetch = originalFetch;
  }
}

    let python = null;
    async function initialize(base, packed, id, resources) {
      self.postMessage({ id, type: 'progress', phase: 'loading', message: 'Loading the search engine…' });
      if (resources) python = await loadOfflinePyodide(resources);
      else {
        const { loadPyodide } = await import(base + 'pyodide.mjs');
        python = await loadPyodide({ indexURL: base, stdout() {}, stderr() {} });
      }
      await python.loadPackage('numpy');
      python.globals.set('_jr_bundle_b64', packed);
      python.runPython(`
import base64, gzip, json, pathlib, sys
_jr_directory = pathlib.Path('/home/pyodide/jr_dtmu')
_jr_directory.mkdir(exist_ok=True)
_jr_files = json.loads(gzip.decompress(base64.b64decode(_jr_bundle_b64)))
for _jr_name, _jr_encoded in _jr_files.items():
    (_jr_directory / _jr_name).write_bytes(base64.b64decode(_jr_encoded))
sys.path.insert(0, str(_jr_directory))
from dtmu_browser_adapter import search_json as _jr_search_json
del _jr_files, _jr_bundle_b64, _jr_name, _jr_encoded
`);
    }
    self.onmessage = async function (event) {
      const { id, matrix, base, packed, resources } = event.data;
      let phase = python ? 'searching' : 'loading';
      try {
        if (!python) await initialize(base, packed, id, resources);
        phase = 'searching';
        self.postMessage({ id, type: 'progress', phase, message: 'Searching for a reddening sequence…' });
        python.globals.set('_jr_request_json', JSON.stringify(matrix));
        let answer;
        try {
          answer = JSON.parse(python.runPython('_jr_search_json(_jr_request_json)'));
        } finally {
          python.globals.delete('_jr_request_json');
          python.runPython('import gc; gc.collect()');
        }
        if (answer.error) self.postMessage({ id, type: 'error', message: answer.message });
        else self.postMessage({ id, type: 'result', result: answer });
      } catch (error) {
        console.error('DTmu ' + phase + ' failed:', error);
        self.postMessage({ id, type: 'error', message: phase === 'loading'
          ? 'The search engine could not start. Refresh the homepage and try again.'
          : 'The search could not finish. Please try again or simplify the quiver.' });
      }
    };
  }

  function disposeWorker() {
    if (worker) worker.terminate();
    if (workerURL) URL.revokeObjectURL(workerURL);
    worker = null; workerURL = null; ready = false;
  }

  function failed(message) {
    return { promise: Promise.reject(new Error(message)), cancel() {} };
  }

  function validMatrix(matrix) {
    return Array.isArray(matrix) && matrix.length > 0 && matrix.length <= 32
      && matrix.every(row => Array.isArray(row) && row.length === matrix.length
        && row.every(Number.isSafeInteger));
  }

  function search(matrix, options = {}) {
    if (!validMatrix(matrix)) return failed('Choose a quiver with 1 to 32 mutable vertices and exact integer arrows.');
    if (active) return failed('A reddening search is already running. Stop it before starting another.');
    if (typeof Worker !== 'function' || typeof Blob !== 'function') {
      return failed('This browser cannot run the search engine. Please use a current browser.');
    }
    const id = ++serial, snapshot = matrix.map(row => row.slice());
    let resolve, reject, timer, settled = false, searching = false;
    const promise = new Promise((yes, no) => { resolve = yes; reject = no; });
    const job = { id };
    active = job;
    function progress(phase, message) {
      if (typeof options.onProgress === 'function') {
        try { options.onProgress({ phase, message }); } catch (_) {}
      }
    }
    function finish(error, result, keepWorker = false) {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      if (!keepWorker) disposeWorker();
      else if (worker) { worker.onmessage = null; worker.onerror = null; worker.onmessageerror = null; }
      if (active === job) active = null;
      if (error) reject(error); else resolve(result);
    }
    function startSearchClock() {
      if (searching) return;
      searching = true; ready = true;
      clearTimeout(timer);
      timer = setTimeout(() => finish(null, {
        status: 'unresolved', sequence: [], attempts: null, optimal: false,
        verified: false, reason: 'time_limit', elapsedSeconds: searchLimit / 1000
      }), searchLimit);
    }
    function cancel() {
      const error = new Error('Search stopped.');
      error.name = 'AbortError';
      finish(error);
    }
    queueMicrotask(async () => {
      if (settled) return;
      try {
        timer = setTimeout(() => finish(new Error('Loading took too long. Refresh the homepage and try again.')), loadingLimit);
        progress(ready ? 'searching' : 'loading', ready ? 'Searching for a reddening sequence…' : 'Loading the search engine…');
        const resources = ready ? null : await loadResources();
        if (settled) return;
        if (!worker) {
          const source = '(' + workerMain.toString() + ')();';
          // Chromium blocks module Blob workers launched from file:// pages.
          // A module data URL works there without relaxing browser security.
          const fromDisk = (typeof location === 'object' && location.protocol === 'file:') || scriptSource?.startsWith('file:');
          if (!fromDisk) workerURL = URL.createObjectURL(new Blob([source], { type: 'text/javascript' }));
          const workerAddress = fromDisk ? 'data:text/javascript;charset=utf-8,' + encodeURIComponent(source) : workerURL;
          worker = new Worker(workerAddress, { type: 'module', name: 'DTmu reddening search' });
        }
        worker.onmessage = function (event) {
          if (settled || event.data?.id !== id) return;
          const message = event.data;
          if (message.type === 'progress') {
            if (message.phase === 'searching') startSearchClock();
            progress(message.phase, message.message);
          } else if (message.type === 'error') {
            finish(new Error(message.message || 'The search could not finish. Please try again.'));
          } else if (message.type === 'result') {
            const answer = message.result;
            if (!answer || !['dt', 'obstruction', 'unresolved'].includes(answer.status)
                || !Array.isArray(answer.sequence)
                || answer.sequence.some(index => !Number.isInteger(index) || index < 1 || index > snapshot.length)
                || (answer.status === 'dt' && (!answer.verified || answer.sequence.length === 0
                  || !Array.isArray(answer.permutation) || answer.permutation.length !== snapshot.length
                  || new Set(answer.permutation).size !== snapshot.length
                  || answer.permutation.some(index => !Number.isSafeInteger(index) || index < 1 || index > snapshot.length)))) {
              finish(new Error('The search returned an invalid result. Please try again.'));
            } else {
              finish(null, answer, true);
            }
          }
        };
        worker.onerror = function (event) {
          event.preventDefault();
          finish(new Error(searching ? 'The search stopped unexpectedly. Please try again.'
            : 'The search engine could not start. Refresh the homepage and try again.'));
        };
        worker.onmessageerror = () => finish(new Error('The search result could not be read. Please try again.'));
        if (ready) startSearchClock();
        worker.postMessage({ id, matrix: snapshot, base: pyodideBase, packed: ready ? null : bundle, resources });
      } catch (error) {
        finish(new Error(error.message || 'The search engine could not start in this browser. Please try a current browser.'));
      }
    });
    return { promise, cancel };
  }

  window.jrDTmu = Object.freeze({ search, version: 'DTmu / Pyodide 314.0.8' });
}());

